def compare_versions(a: str, b: str) -> int:
    def parse(v: str):
        # Remove build metadata (everything after '+')
        core_part = v.split('+')[0]
        # Separate core version and pre-release (split on first '-')
        if '-' in core_part:
            core_str, pre_str = core_part.split('-', 1)
            pre_segments = pre_str.split('.')
        else:
            core_str = core_part
            pre_segments = None

        core_tuple = tuple(int(x) for x in core_str.split('.'))
        return core_tuple, pre_segments

    core_a, pre_a = parse(a)
    core_b, pre_b = parse(b)

    # 1. Compare Core Version (Major, Minor, Patch)
    if core_a < core_b:
        return -1
    if core_a > core_b:
        return 1

    # 2. Core versions are equal, handle pre-release logic
    # A version with a pre-release is lower than a version without one
    if pre_a is None and pre_b is None:
        return 0
    if pre_a is not None and pre_b is None:
        return -1
    if pre_a is None and pre_b is not None:
        return 1

    # 3. Both have pre-releases, compare segments dot by dot
    for seg_a, seg_b in zip(pre_a, pre_b):
        # Determine if segments are numeric
        is_a_num = seg_a.isdigit()
        is_b_num = seg_b.isdigit()

        if is_a_num and is_b_num:
            # Numeric comparison
            val_a, val_b = int(seg_a), int(seg_b)
            if val_a != val_b:
                return -1 if val_a < val_b else 1
        elif is_a_num != is_b_num:
            # Numeric identifiers have lower precedence than non-numeric
            return -1 if is_a_num else 1
        else:
            # Alphanumeric comparison
            if seg_a != seg_b:
                return -1 if seg_a < seg_b else 1

    # 4. If all compared segments were equal, the shorter list of segments is lower
    if len(pre_a) < len(pre_b):
        return -1
    if len(pre_a) > len(pre_b):
        return 1

    return 0
