import heapq

def build_order(deps: dict[str, list[str]]) -> list[str]:
    # Identify all unique nodes in the graph
    all_nodes = set(deps.keys())
    for dependencies in deps.values():
        all_nodes.update(dependencies)

    # Initialize in-degree and adjacency list
    in_degree = {node: 0 for node in all_nodes}
    adj = {node: [] for node in all_nodes}

    # Build the graph: edge goes from dependency -> item
    for item, dependencies in deps.items():
        for dep in dependencies:
            adj[dep].append(item)
            in_degree[item] += 1

    # Kahn's algorithm using a min-heap to handle alphabetical requirement
    ready = [node for node in all_nodes if in_degree[node] == 0]
    heapq.heapify(ready)

    order = []
    while ready:
        u = heapq.heappop(ready)
        order.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(ready, v)

    # If order length doesn't match total nodes, there is a cycle
    if len(order) != len(all_nodes):
        raise ValueError("A cycle exists in the dependency graph.")

    return order
