def build_order(deps: dict[str, list[str]]) -> list[str]:
    # Identify all unique items involved
    nodes = set(deps.keys())
    for neighbors in deps.values():
        nodes.update(neighbors)

    # Initialize in-degree and adjacency list
    in_degree = {node: 0 for node in nodes}
    adj = {node: [] for node in nodes}

    # Build the graph
    # If A depends on B, B is the prerequisite (B -> A)
    for item, dependencies in deps.items():
        for dep in dependencies:
            adj[dep].append(item)
            in_degree[item] += 1

    # Kahn's algorithm using a min-priority queue for alphabetical tie-breaking
    queue = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(queue)

    result = []
    while queue:
        current = heapq.heappop(queue)
        result.append(current)

        for neighbor in adj[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
