        # Parse ISO 8601 string. Replacing 'Z' with '+00:00' for compatibility 
        # with versions of Python prior to 3.11.
        dt = datetime.fromisoformat(record['updated_at'].replace('Z', '+00:00'))

        if val not in best_records:
            order.append(val)
            best_records[val] = (dt, i, record)
        else:
            existing_dt, existing_idx, _ = best_records[val]
            # Keep if timestamp is later, or if timestamps are equal and it appears later in the list
            if dt > existing_dt or (dt == existing_dt and i > existing_idx):
                best_records[val] = (dt, i, record)

    return [best_records[v][2] for v in order]
