from decimal import Decimal
import re

def parse_brl(s: str) -> Decimal:
    s = s.strip()
    if not s:
        raise ValueError("Empty string")

    is_negative = False
    if s.startswith('(') and s.endswith(')'):
        is_negative = True
        s = s[1:-1].strip()
    elif s.startswith('-'):
        is_negative = True
        s = s[1:].strip()

    s = s.replace('R$', '').strip()

    if not s:
        raise ValueError("Invalid format")

    if ',' in s:
        parts = s.split(',')
        if len(parts) != 2:
            raise ValueError("Invalid decimal separator usage")

        int_part_str, cent_part_str = parts

        if len(cent_part_str) != 2 or not cent_part_str.isdigit():
            raise ValueError("Cents must be exactly 2 digits")

        # Validate integer part with comma present
        if not int_part_str:
            raise ValueError("Missing integer part")

        if '.' in int_part_str:
            # If dots exist, they must group digits in exactly 3s
            if not re.fullmatch(r'\d+(\.\d{3})*', int_part_str):
                raise ValueError("Invalid integer grouping")
        else:
            if not int_part_str.isdigit():
                raise ValueError("Integer part must be digits")

        integer_val = int(int_part_str.replace('.', ''))
        cents_val = int(cent_part_str)
        result = Decimal(f"{integer_val}.{cents_val:02d}")
    else:
        # No comma: integer part only, no cents
        if not s:
            raise ValueError("Empty string")

        # Must be plain digits OR digits grouped by '.' in groups of 3
        if re.fullmatch(r'\d+(\.\d{3})*', s):
            result = Decimal(s.replace('.', ''))
        elif s.isdigit():
            result = Decimal(s)
        else:
            raise ValueError("Invalid integer format")

    if is_negative:
        result = -result

    return result
