        # NFD decomposes characters (e.g., 'á' -> 'a' + 'combining acute accent')
        normalized_chars = []
        has_accent = False
        for char in unicodedata.normalize('NFD', name):
            if unicodedata.category(char) == 'Mn':
                has_accent = True
            else:
                normalized_chars.append(char)

        normalized_name = "".join(normalized_chars).lower()

        # 2. The key tuple:
        # - normalized name (primary)
        # - whether it has accents (secondary: False/0 comes before True/1)
        # - original name (tertiary)
        return (normalized_name, has_accent, name)

    return sorted(names, key=sort_key)
