def set_ini_value(text: str, section: str, key: str, value: str) -> str:
    lines = text.splitlines(keepends=True)
    new_lines = []
    in_target_section = False
    section_found = False
    key_found = False

    for line in lines:
        stripped = line.strip()

        # Check for section header: [section_name]
        if stripped.startswith('[') and ']' in stripped:
            # Extract section name, handling potential trailing comments if needed,
            # but prompt says comment lines start with ; or #, so we assume [section]
            # is the standard format.
            current_section = stripped[1:stripped.rfind(']')]

            if current_section == section:
                if in_target_section and not key_found:
                    raise KeyError(f"Key '{key}' not found in section '{section}'")
                in_target_section = True
                section_found = True
            else:
                if in_target_section:
                    if not key_found:
                        raise KeyError(f"Key '{key}' not found in section '{section}'")
                    in_target_section = False

        # If we are in the target section, look for the key
        if in_target_section and not key_found:
            # Check if line is a comment or blank
            if stripped and not stripped.startswith((';', '#')):
                if '=' in line:
                    # Split only on the first '='
                    parts = line.split('=', 1)
                    if parts[0].strip() == key:
                        new_lines.append(f"{key} = {value}\n")
                        key_found = True
                        # Do not set in_target_section to False yet, 
                        # in case there are multiple instances of the same key in the same section
                        # (though INI usually expects one, we must stay in section)
                        continue

        new_lines.append(line)

    if not section_found:
        raise KeyError(f"Section '{section}' not found")
    if not key_found:
        raise KeyError(f"Key '{key}' not found in section '{section}'")

    return "".join(new_lines)
